def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a recursive descent parsing technique. 
    The parser goes through the input string character by character to identify 
    the structure and types of JSON elements.
    """
    pos = 0
    length = len(s)

    def parse_value():
        nonlocal pos
        if pos >= length:
            raise ValueError("Unexpected end of input")

        char = s[pos]

        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif s[pos:pos + 4] == "true":
            pos += 4
            return True
        elif s[pos:pos + 5] == "false":
            pos += 5
            return False
        elif s[pos:pos + 4] == "null":
            pos += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: '{char}'")

    def parse_string():
        nonlocal pos
        pos += 1  # skip the opening quote
        start = pos
        string_builder = []
        while pos < length:
            char = s[pos]
            if char == '"':
                break
            elif char == '\\':
                pos += 1
                escape = s[pos]
                if escape == 'n':
                    string_builder.append('\n')
                elif escape == 't':
                    string_builder.append('\t')
                elif escape == 'r':
                    string_builder.append('\r')
                elif escape == 'b':
                    string_builder.append('\b')
                elif escape == 'f':
                    string_builder.append('\f')
                elif escape == '"':
                    string_builder.append('"')
                elif escape == '\\':
                    string_builder.append('\\')
                else:
                    string_builder.append(escape)  # handle unicode or a weird escape
            else:
                string_builder.append(char)
            pos += 1
        pos += 1  # skip the closing quote
        return ''.join(string_builder)

    def parse_number():
        nonlocal pos
        start = pos
        if s[pos] == '-':
            pos += 1
        while pos < length and (s[pos].isdigit() or s[pos] == '.'):
            pos += 1
        number = s[start:pos]
        if '.' in number:
            return float(number)
        else:
            return int(number)

    def parse_array():
        nonlocal pos
        pos += 1  # skip opening bracket
        array = []
        while pos < length:
            char = s[pos]
            if char == ']':
                pos += 1  # skip closing bracket
                return array
            array.append(parse_value())
            if s[pos] == ',':
                pos += 1  # skip comma
            elif s[pos] == ']':
                continue
            else:
                raise ValueError(f"Expected ',' or ']', found: '{char}'")

    def parse_object():
        nonlocal pos
        pos += 1  # skip opening brace
        obj = {}
        while pos < length:
            char = s[pos]
            if char == '}':
                pos += 1  # skip closing brace
                return obj
            key = parse_string()
            if s[pos] != ':':
                raise ValueError(f"Expected ':', found: '{s[pos]}'")
            pos += 1  # skip colon
            value = parse_value()
            obj[key] = value
            if s[pos] == ',':
                pos += 1  # skip comma
            elif s[pos] == '}':
                continue
            else:
                raise ValueError(f"Expected ',' or '}', found: '{char}'")

    return parse_value()

