                    raise ValueError(f"Expected ',' or ']', found: '{self.s[self.pos]}'")

        def parse_object(self):
            self.pos += 1  # skip opening brace
            self.skip_whitespace()
            obj = {}
            while self.pos < self.length:
                if self.s[self.pos] == '}':
                    self.pos += 1  # skip closing brace
                    return obj
                key = self.parse_string()
                self.skip_whitespace()
                if self.s[self.pos] != ':':
