                    raise ValueError(f"Expected ',' or '}', found: '{self.s[self.pos]}'")

        def skip_whitespace(self):
            while self.pos < self.length and self.s[self.pos].isspace():
                self.pos += 1

    parser = Parser(s)
    return parser.parse()

